function ref = mfun_ovhz_reference_generator(u_dc, tau_M_ref, fbk_in, p)
%MFUN_OVHZ_REFERENCE_GENERATOR Block ReferenceGenerator of the control system.
%   ReferenceGenerator of motulator. Generated by motulator_export from the MATLAB port
%   of motulator and called by the MATLAB Function block of the Simulink model, which
%   adds its folder to the MATLAB path. The parameters are the fields of the struct p
%   (from the mask, [] as NaN). The state is in persistent variables, of which each
%   MATLAB Function block has its own copy.
persistent self
if isempty(self)
    % Machine model (InductionMachineInvGammaPars)
    par = struct('n_p', p.par_n_p, 'R_s', p.par_R_s, 'R_R', p.par_R_R, ...
        'L_sgm', p.par_L_sgm, 'L_M', p.par_L_M);
    self = im_flux_reference_gen_init(par, p.psi_s_nom, p.i_s_max, p.tau_M_max, ...
        p.k_u, p.k_b);
end
fbk = im_observer_outputs_unpack(fbk_in);
% Flux and limited torque references (ref.psi_s, ref.tau_M)
[psi_s_ref, tau_M_lim] = im_reference_gen_flux_and_torque(self, tau_M_ref, ...
    fbk.w_s, abs(fbk.psi_R), u_dc);
ref = [psi_s_ref; tau_M_lim];
end

function s = im_observer_outputs_unpack(u)
%IM_OBSERVER_OUTPUTS_UNPACK Struct of the signal vector u.
s = struct( ...
    'i_s', complex(u(1), u(2)), ...
    'u_s', complex(u(3), u(4)), ...
    'u_s_zoh', complex(u(5), u(6)), ...
    'psi_s', complex(u(7), u(8)), ...
    'psi_R', complex(u(9), u(10)), ...
    'tau_M', u(11), ...
    'w_c', u(12), ...
    'w_s', u(13), ...
    'w_r', u(14), ...
    'w_m', u(15), ...
    'w_M', u(16), ...
    'theta_c', u(17), ...
    'e_o', complex(u(18), u(19)), ...
    'eps', u(20), ...
    'h', u(21));
end

function y = py_min(a, b)
%PY_MIN Minimum as the built-in min of Python: the first argument unless the second
%   one is smaller, so that a NaN argument is skipped unless it is the first one.
if b < a
    y = b;
else
    y = a;
end
end

function self = im_flux_reference_gen_init(par, psi_s_nom, i_s_max, tau_M_max, k_u, ...
    k_b)
%IM_FLUX_REFERENCE_GEN_INIT Reference generator with field weakening and torque
%   limits (ReferenceGenerator).
self = struct('par', par, 'psi_s_nom', psi_s_nom, 'i_s_max', i_s_max, ...
    'tau_M_max', tau_M_max, 'k_u', k_u, 'k_b', k_b);
end

function [psi_s_ref, tau_M_ref] = im_reference_gen_flux_and_torque(self, tau_M_ref, ...
    w_s, psi_R, u_dc)
%IM_REFERENCE_GEN_FLUX_AND_TORQUE Stator flux reference and limited torque
%   reference.
par = self.par;
% Field weakening
u_s_max = self.k_u*u_dc/sqrt(3);
if w_s ~= 0
    psi_s_max = u_s_max/abs(w_s);
else
    psi_s_max = Inf;
end
% Current limit
psi_s_cl = par.L_sgm*self.i_s_max + psi_R;
% Stator flux reference
psi = py_min(py_min(psi_s_max, self.psi_s_nom), psi_s_cl);
% Torque reference limiting
if par.L_sgm > 0 % L_sgm = 0 in open-loop V/Hz control
    % Breakdown torque limit
    k = self.k_b*par.L_M/(par.L_M + par.L_sgm);
    tau_b = 0.75*par.n_p*k*(psi*psi)/par.L_sgm;
    % Current limit
    i_m = psi_R/par.L_M;
    tau_M_cl = 0;
    if psi_R < par.L_M*self.i_s_max
        i_q_max = sqrt(self.i_s_max*self.i_s_max - i_m*i_m);
        tau_M_cl = 1.5*par.n_p*psi_R*i_q_max;
    end
    % Limited torque reference
    tau = py_min(py_min(py_min(abs(tau_M_ref), self.tau_M_max), tau_b), tau_M_cl);
    tau_M_ref = tau*sign(tau_M_ref);
end
psi_s_ref = psi;
end
